static void *malloc_wrapper(size_t size)
{
	if(in_atomic() || irqs_disabled() || in_interrupt())
		return kmalloc(size,GFP_ATOMIC);

	if(size > 32*1024) {
		/*
		 * Workarround for 32bit systems
		 * Large memory areas (more than 128 KB) are requested
		 * only during initial initialization.
		 * In this case, we can use kvmalloc() instead of kmalloc().
		 */
#if LINUX_VERSION_CODE >= KERNEL_VERSION(4,12,0)
		return kvmalloc(size,GFP_KERNEL);
#else
		return vmalloc(size);
#endif
	}
	return kmalloc(size,GFP_KERNEL);
}

static void free_wrapper(void *freeable)
{
	kvfree(freeable);
}

static void *realloc_wrapper(void *ptr, size_t size) {
	void *p = malloc_wrapper(size);
	if(!p) return NULL;
	if(ptr) {
		memcpy(p,ptr,size);
		kvfree(ptr);
	}
	return p;
}

static void *calloc_wrapper(size_t nmemb, size_t size) {
	void *p = malloc_wrapper(nmemb*size);
	if(p)
		memset(p,0,nmemb*size);
	return p;
}

static void *aligned_malloc_wrapper(size_t alignment, size_t size) {
	return malloc_wrapper(size);
}

#include <linux/xarray.h>
#include <linux/overflow.h>
#include <linux/mm.h>

/* kmalloc keeps its own size; vmalloc realloc needs the requested length. */
static DEFINE_XARRAY(ndpi_vmalloc_sizes);

static void *malloc_wrapper(size_t size)
{
	void *p;

	if (size > (SIZE_MAX >> 1))
		return NULL;
	if (in_atomic() || irqs_disabled() || in_interrupt())
		return kmalloc(size, GFP_ATOMIC);
	if (size <= 32 * 1024)
		return kmalloc(size, GFP_KERNEL);
	p = kvmalloc(size, GFP_KERNEL);
	if (is_vmalloc_addr(p)) {
		void *old = xa_store(&ndpi_vmalloc_sizes,
				    (unsigned long)p >> PAGE_SHIFT,
				    xa_mk_value(size), GFP_KERNEL);
		if (xa_is_err(old)) {
			kvfree(p);
			return NULL;
		}
	}
	return p;
}

static void free_wrapper(void *freeable)
{
	if (is_vmalloc_addr(freeable))
		xa_erase(&ndpi_vmalloc_sizes,
			 (unsigned long)freeable >> PAGE_SHIFT);
	kvfree(freeable);
}

static void *realloc_wrapper(void *ptr, size_t size)
{
	bool atomic = in_atomic() || irqs_disabled() || in_interrupt();
	void *entry, *p;
	size_t old_size;

	if (!ptr)
		return malloc_wrapper(size);
	if (size > (SIZE_MAX >> 1))
		return NULL;
	if (!is_vmalloc_addr(ptr))
		return krealloc(ptr, size, atomic ? GFP_ATOMIC : GFP_KERNEL);
	/* vmalloc work must not sleep while a packet-path lock is held. */
	if (atomic)
		return NULL;
	entry = xa_load(&ndpi_vmalloc_sizes, (unsigned long)ptr >> PAGE_SHIFT);
	if (!xa_is_value(entry))
		return NULL;
	old_size = xa_to_value(entry);
	if (!size) {
		free_wrapper(ptr);
		return ZERO_SIZE_PTR;
	}
	p = malloc_wrapper(size);
	if (!p)
		return NULL;
	memcpy(p, ptr, min_t(size_t, old_size, size));
	free_wrapper(ptr);
	return p;
}

static void *calloc_wrapper(size_t nmemb, size_t size)
{
	size_t total;
	void *p;

	if (check_mul_overflow(nmemb, size, &total))
		return NULL;
	p = malloc_wrapper(total);
	if (p)
		memset(p, 0, total);
	return p;
}

static void *aligned_malloc_wrapper(size_t alignment, size_t size)
{
	return malloc_wrapper(size);
}
